    public static let espalda = Silueta(contorno: frente.contorno, detalle: "M60 40 C60.0 45.0 60.0 58.0 60 70 C60.0 82.0 60.0 105.0 60 112 M45 58 C45.8 59.7 48.2 65.7 50 68 C51.8 70.3 55.0 71.3 56 72 M75 58 C74.2 59.7 71.8 65.7 70 68 C68.2 70.3 65.0 71.3 64 72 M46 126 C47.2 126.8 50.7 130.8 53 131 C55.3 131.2 58.8 127.7 60 127 M74 126 C72.8 126.8 69.3 130.8 67 131 C64.7 131.2 61.2 127.7 60 127")

    public enum Orden: Equatable, Sendable { case mover(Double, Double), curva(Double, Double, Double, Double, Double, Double), cerrar }

    /// El trazo en órdenes, para dibujarlo con el trazador de cada plataforma. Lo que no entiende lo saltea.
    public static func ordenes(_ trazo: String) -> [Orden] {
        var salida: [Orden] = []
        var letra: Character?
        var numeros: [Double] = []
        func cerrarOrden() {
            switch letra {
            case "M" where numeros.count == 2: salida.append(.mover(numeros[0], numeros[1]))
            case "C" where numeros.count == 6: salida.append(.curva(numeros[0], numeros[1], numeros[2], numeros[3], numeros[4], numeros[5]))
            case "Z": salida.append(.cerrar)
            default: break
            }
            numeros = []
        }
        for parte in trazo.split(separator: " ") {
            guard let primera = parte.first else { continue }
            if primera.isLetter {
                cerrarOrden()
                letra = primera
                if let n = Double(parte.dropFirst()) { numeros.append(n) }
            } else if let n = Double(parte) {
                numeros.append(n)
            }
        }
        cerrarOrden()
        return salida
    }
}
